    ["Moveset"] = [=[
local Moveset = {}

function Moveset.Init(State, Helpers)
    local toggleObject = State.Toggles.Moveset
    local m_floor = Helpers.m_floor
    local m_clamp = Helpers.m_clamp
    local SPECIAL_COOLDOWNS = Helpers.SPECIAL_COOLDOWNS
    local m_max = Helpers.m_max
    local o_clock = Helpers.o_clock
    local table_insert = Helpers.table_insert
    local v2_new = Helpers.v2_new
    local COLOR_LIGHT_BLUE = Helpers.COLOR_LIGHT_BLUE
    local COLOR_BLACK = Helpers.COLOR_BLACK
    local COLOR_SEAL_RED = Helpers.COLOR_SEAL_RED
    local COLOR_SEAL_GREEN = Helpers.COLOR_SEAL_GREEN

    local function Hide(c)
        for i = 0, 5 do
            local item = c.MovesetItems[i]
            item.Back.Visible = false
            item.Fill.Visible = false
            item.Outline.Visible = false
            item.Label.Visible = false
            item.SealCircle.Visible = false
        end
    end

    local function Render(c, movesetName, movesetFolder, isReggie, nextReceiptObj, scaleFactor, root2D, uY, noCooldown)
        if not toggleObject.Value then Hide(c); return end
        -- 5. Moveset Slots
        local slotHeight = m_floor(m_clamp(22 * scaleFactor, 14, 32))
        local slotGap = m_floor(m_clamp(3 * scaleFactor, 2, 6))
        local moveFontSize = m_floor(m_clamp(10 * scaleFactor, 8, 15))
        local slotY = uY - slotHeight - m_floor(m_clamp(4 * scaleFactor, 2, 8))
        local hasActiveMoveset = false
    
        if c.MovesetItems then
            -- Reset visibility
            for i = 0, 5 do
                c.MovesetItems[i].Data.Visible = false
                c.MovesetItems[i].MoveRef = nil
            end
    
            -- Slot 0: Special
            local specialItem = c.MovesetItems[0]
            specialItem.Data.Visible = true
            specialItem.Data.Key = "0"
            -- Determine name based on current moveset
            local specData = SPECIAL_COOLDOWNS[movesetName]
            if specData then
                specialItem.Data.Name = specData.Name
                local remaining = not noCooldown and m_max(0, c.SpecialCooldownEnd - o_clock()) or 0
                local cdRatio = m_clamp(remaining / specData.Duration, 0, 1)
                specialItem.Data.CooldownRatio = cdRatio
            else
                specialItem.Data.Name = "Special"
                specialItem.Data.CooldownRatio = 0
            end
            specialItem.MoveRef = nil
            hasActiveMoveset = true
    
            -- Slots 1-4: regular moves
            if movesetFolder then
                for _, move in ipairs(movesetFolder:GetChildren()) do
                    local slotKey = move:GetAttribute("Key")
                    if type(slotKey) == "number" and slotKey >= 1 and slotKey <= 4 then
                        local item = c.MovesetItems[slotKey]
                        if item then
                            hasActiveMoveset = true
                            item.Data.Visible = true
                            item.Data.Key = tostring(slotKey)
                            local tag = move:GetAttribute("Tag")
                            if tag and move.Name ~= "-" then
                                item.Data.Name = tostring(tag)
                                if not item._tagConn then
                                    item._tagConn = move:GetAttributeChangedSignal("Tag"):Connect(function()
                                        local newTag = move:GetAttribute("Tag")
                                        if newTag and move.Name ~= "-" then
                                            item.Data.Name = tostring(newTag)
                                        else
                                            item.Data.Name = move.Name
                                        end
                                    end)
                                    table_insert(c.Connections, item._tagConn)
                                end
                            else
                                item.Data.Name = move.Name
                            end
                            item.MoveRef = move
    
                            if noCooldown then
                                item.Data.CooldownRatio = 0
                            else
                                local lastUsedStamp = move:GetAttribute("LastUse")
                                local totalCdDuration = tonumber(move.Value)
                                if type(lastUsedStamp) == "number" and type(totalCdDuration) == "number" and totalCdDuration > 0 then
                                    local serverNow = workspace:GetServerTimeNow()
                                    local remainingCd = (lastUsedStamp + totalCdDuration) - serverNow
                                    item.Data.CooldownRatio = m_clamp(remainingCd / totalCdDuration, 0, 1)
                                else
                                    item.Data.CooldownRatio = 0
                                end
                            end
                        end
                    end
                end
            end
    
            -- Slot 5: extra for Reggie
            local reggieItem = c.MovesetItems[5]
            if isReggie and nextReceiptObj then
                reggieItem.Data.Visible = true
                reggieItem.Data.Key = "5"
                local function updateReceipt()
                    reggieItem.Data.Name = tostring(nextReceiptObj.Value)
                end
                updateReceipt()
                if not c._receiptConn then
                    c._receiptConn = nextReceiptObj:GetPropertyChangedSignal("Value"):Connect(updateReceipt)
                    table_insert(c.Connections, c._receiptConn)
                end
                reggieItem.Data.CooldownRatio = 0
                reggieItem.MoveRef = nil
                hasActiveMoveset = true
            else
                reggieItem.Data.Visible = false
            end
    
            -- Compute widths for slots 0-4
            local itemWidths = {}
            local totalMovesetWidth = 0
            local activeCount = 0
            for i = 0, 4 do
                local item = c.MovesetItems[i]
                if item.Data.Visible then
                    activeCount = activeCount + 1
                    item.Label.Text = item.Data.Name
                    item.Label.Size = moveFontSize
                    local textW = item.Label.TextBounds.X
                    local slotW = m_floor(m_max(slotHeight, textW + m_clamp(8 * scaleFactor, 4, 12)))
                    slotW = m_floor(m_max(slotW, slotHeight))
                    itemWidths[i] = slotW
                    totalMovesetWidth = totalMovesetWidth + slotW
                else
                    itemWidths[i] = 0
                end
            end
            if activeCount > 0 then
                totalMovesetWidth = totalMovesetWidth + ((activeCount - 1) * slotGap)
            end
    
            -- Render slots 0-4 centered
            local movesetStartX = m_floor(root2D.X - (totalMovesetWidth / 2))
            local currentSlotX = movesetStartX
            for i = 0, 4 do
                local item = c.MovesetItems[i]
                if item.Data.Visible then
                    local slotW = itemWidths[i]
                    item.Back.Visible = true
                    item.Back.Position = v2_new(currentSlotX, slotY)
                    item.Back.Size = v2_new(slotW, slotHeight)
    
                    item.Outline.Visible = true
                    item.Outline.Position = v2_new(currentSlotX, slotY)
                    item.Outline.Size = v2_new(slotW, slotHeight)
    
                    local cdRatio = item.Data.CooldownRatio
                    if cdRatio > 0 then
                        local cdFillH = m_floor(slotHeight * cdRatio)
                        item.Fill.Visible = true
                        item.Fill.Color = COLOR_LIGHT_BLUE
                        item.Fill.Transparency = 0.5
                        item.Fill.Size = v2_new(slotW, cdFillH)
                        item.Fill.Position = v2_new(currentSlotX, slotY + (slotHeight - cdFillH))
                    else
                        item.Fill.Visible = false
                    end
    
                    item.Label.Visible = true
                    item.Label.Outline = true
                    item.Label.OutlineColor = COLOR_BLACK
                    item.Label.Text = item.Data.Name
                    item.Label.Size = moveFontSize
                    item.Label.Position = v2_new(currentSlotX + m_floor(slotW / 2), slotY + m_floor((slotHeight - item.Label.TextBounds.Y) / 2))
    
                    local seal = item.MoveRef and item.MoveRef:GetAttribute("Seal")
                    if seal then
                        local radius = m_floor(m_clamp(4 * scaleFactor, 3, 8))
                        local padding = m_floor(m_clamp(2 * scaleFactor, 1, 4))
                        item.SealCircle.Visible = true
                        item.SealCircle.Radius = radius
                        if seal == 1 then
                            item.SealCircle.Color = COLOR_SEAL_RED
                        else -- seal > 1
                            item.SealCircle.Color = COLOR_SEAL_GREEN
                        end
                        item.SealCircle.Position = v2_new(currentSlotX + slotW - radius - padding, slotY + padding + radius * 0.5)
                    else
                        item.SealCircle.Visible = false
                    end
    
                    currentSlotX = currentSlotX + slotW + slotGap
                else
                    item.Back.Visible = false
                    item.Fill.Visible = false
                    item.Outline.Visible = false
                    item.Label.Visible = false
                    item.SealCircle.Visible = false
                end
            end
    
            -- Render Reggie slot 5 to the right
            if reggieItem and reggieItem.Data.Visible then
                local lastSlotEnd = currentSlotX - slotGap
                reggieItem.Label.Text = reggieItem.Data.Name
                reggieItem.Label.Size = moveFontSize
                local textW = reggieItem.Label.TextBounds.X
                local reggieWidth = m_floor(m_max(slotHeight, textW + m_clamp(8 * scaleFactor, 4, 12)))
                reggieWidth = m_floor(m_clamp(reggieWidth, slotHeight, 80))
                local reggieX = lastSlotEnd + slotGap
                reggieItem.Back.Visible = true
                reggieItem.Back.Position = v2_new(reggieX, slotY)
                reggieItem.Back.Size = v2_new(reggieWidth, slotHeight)
                reggieItem.Outline.Visible = true
                reggieItem.Outline.Position = v2_new(reggieX, slotY)
                reggieItem.Outline.Size = v2_new(reggieWidth, slotHeight)
                reggieItem.Fill.Visible = false
                reggieItem.Label.Visible = true
                reggieItem.Label.Outline = true
                reggieItem.Label.OutlineColor = COLOR_BLACK
                reggieItem.Label.Text = reggieItem.Data.Name
                reggieItem.Label.Size = moveFontSize
                reggieItem.Label.Position = v2_new(reggieX + m_floor(reggieWidth / 2), slotY + m_floor((slotHeight - reggieItem.Label.TextBounds.Y) / 2))
                reggieItem.SealCircle.Visible = false
            else
                reggieItem.Back.Visible = false
                reggieItem.Fill.Visible = false
                reggieItem.Outline.Visible = false
                reggieItem.Label.Visible = false
                reggieItem.SealCircle.Visible = false
            end
        end
        return hasActiveMoveset, slotY
    end

    return { Render = Render, Hide = Hide }
end

return Moveset
]=],
    ["Noclip"] = [=[
local Noclip = {}

local charFolder = workspace:WaitForChild("Characters")
local RunService = cloneref(game:GetService("RunService"))
local Players = cloneref(game:GetService("Players"))
local localPlayer = Players.LocalPlayer

local TARGET_NAMES = {
    Head = true,
    Torso = true,
    ["Left Leg"] = true,
    ["Right Leg"] = true,
    ["Left Arm"] = true,
    ["Right Arm"] = true,
    Collide = true,
    Mask = true,
}

-- Only these parts are checked each frame. The old version rescanned every
-- character and every child on every frame.
local trackedParts = {}
local originalCollision = {}
local characterStates = {}

local runtimeConnections = {}
local enabled = false

local function disconnect(connection)
    if connection then
        connection:Disconnect()
    end
end

local function rememberOriginalState(part)
    if originalCollision[part] == nil then
        originalCollision[part] = part.CanCollide and 1 or 0
    end
end

local function trackPart(part, character, canCollide)
    if not part or not part.Parent or not part:IsA("BasePart") then
        return
    end

    rememberOriginalState(part)
    trackedParts[part] = {
        character = character,
        canCollide = canCollide,
    }

    local characterState = characterStates[character]
    if enabled and characterState and not characterState.dead and part.CanCollide ~= canCollide then
        part.CanCollide = canCollide
    end
end

local function untrackCharacter(character, discardOriginal)
    for part, state in pairs(trackedParts) do
        if state.character == character then
            trackedParts[part] = nil
            if discardOriginal then
                originalCollision[part] = nil
            end
        end
    end
end

local function trackNormalPart(part, character, moveset)
    if not part:IsA("BasePart") then
        return
    end

    local parent = part.Parent

    if parent == character and TARGET_NAMES[part.Name] then
        trackPart(part, character, false)
        return
    end

    -- Some body parts contain an additional collision part.
    if part.Name == "Collide"
        and parent
        and parent.Parent == character
        and TARGET_NAMES[parent.Name]
    then
        trackPart(part, character, false)
        return
    end

    if moveset == "Gojo"
        and part.Name == "Mask"
        and parent
        and parent.Name == "GojoMask"
        and parent.Parent
        and parent.Parent.Name == "SetAssets"
        and parent.Parent.Parent == character
    then
        trackPart(part, character, false)
    elseif moveset == "Hanami"
        and part.Name == "ArmWrap"
        and parent
        and parent.Name == "SetAssets"
        and parent.Parent == character
    then
        trackPart(part, character, false)
    end
end

local function rebuildCharacter(character)
    local state = characterStates[character]
    if not state or state.dead or character == localPlayer.Character or not character.Parent then
        return
    end

    untrackCharacter(character)

    if character.Name == "FrameNPC" then
        local torso = character:FindFirstChild("Torso")
        if torso then
            trackPart(torso, character, false)
        else
            character:Destroy()
        end
        return
    end

    if character.Name == "MechamaruBot" then
        trackPart(character:FindFirstChild("Torso"), character, true)
        trackPart(character:FindFirstChild("Head"), character, false)
        return
    end

    if character.Name == "HarutaSwordNPC" then
        local sword = character:FindFirstChild("HarutaSword")
        local hand = sword and sword:FindFirstChild("Hand")
        trackPart(hand and hand:FindFirstChild("Handle"), character, false)
        return
    end

    for _, descendant in ipairs(character:GetDescendants()) do
        trackNormalPart(descendant, character, state.moveset)
    end
end

local function removeCharacter(character)
    local state = characterStates[character]
    if not state then
        return
    end

    disconnect(state.deadChanged)
    disconnect(state.movesetChanged)
    disconnect(state.descendantAdded)
    disconnect(state.descendantRemoving)

    untrackCharacter(character, true)
    characterStates[character] = nil
end

local function addCharacter(character)
    if character == localPlayer.Character or characterStates[character] then
        return
    end

    local state = {
        dead = character:GetAttribute("Dead") == true,
        moveset = character:GetAttribute("Moveset"),
    }
    characterStates[character] = state

    state.deadChanged = character:GetAttributeChangedSignal("Dead"):Connect(function()
        state.dead = character:GetAttribute("Dead") == true
        if not state.dead then
            rebuildCharacter(character)
        end
    end)

    state.movesetChanged = character:GetAttributeChangedSignal("Moveset"):Connect(function()
        state.moveset = character:GetAttribute("Moveset")
        rebuildCharacter(character)
    end)

    state.descendantAdded = character.DescendantAdded:Connect(function(descendant)
        if state.dead then
            return
        end

        if character.Name == "FrameNPC"
            or character.Name == "MechamaruBot"
            or character.Name == "HarutaSwordNPC"
        then
            rebuildCharacter(character)
        elseif descendant:IsA("BasePart") then
            trackNormalPart(descendant, character, state.moveset)
        end
    end)

    state.descendantRemoving = character.DescendantRemoving:Connect(function(descendant)
        trackedParts[descendant] = nil
        originalCollision[descendant] = nil
    end)

    rebuildCharacter(character)
end

local function stopNoclip()
    enabled = false

    for _, connection in ipairs(runtimeConnections) do
        disconnect(connection)
    end
    table.clear(runtimeConnections)

    for part, originalState in pairs(originalCollision) do
        if part and part.Parent then
            part.CanCollide = originalState == 1
        end
    end

    for character in pairs(characterStates) do
        removeCharacter(character)
    end

    table.clear(trackedParts)
    table.clear(originalCollision)
end

local function startNoclip()
    if enabled then
        return
    end

    enabled = true

    runtimeConnections[#runtimeConnections + 1] = charFolder.ChildAdded:Connect(addCharacter)
    runtimeConnections[#runtimeConnections + 1] = charFolder.ChildRemoved:Connect(removeCharacter)

    for _, character in ipairs(charFolder:GetChildren()) do
        addCharacter(character)
    end

    runtimeConnections[#runtimeConnections + 1] = RunService.Stepped:Connect(function()
        for part, state in pairs(trackedParts) do
            local characterState = characterStates[state.character]

            if not part.Parent or not characterState then
                trackedParts[part] = nil
                originalCollision[part] = nil
            elseif state.character == localPlayer.Character then
                part.CanCollide = originalCollision[part] == 1
                trackedParts[part] = nil
                originalCollision[part] = nil
            elseif not characterState.dead and part.CanCollide ~= state.canCollide then
                part.CanCollide = state.canCollide
            end
        end
    end)
end

function Noclip.Init(State)
    local toggle = State.Toggles.Noclip

    local toggleConnection = toggle:GetPropertyChangedSignal("Value"):Connect(function()
        if toggle.Value then
            startNoclip()
        else
            stopNoclip()
        end
    end)
    table.insert(State.Connections, toggleConnection)

    if toggle.Value then
        startNoclip()
    end
end

return Noclip
]=],
    ["PlayerInfo"] = [=[
local PlayerInfo = {}

function PlayerInfo.Init(State, Helpers)
    local toggleObject = State.Toggles.PlayerInfo
    local table_insert = Helpers.table_insert
    local c3_fromHex = Helpers.c3_fromHex
    local m_floor = Helpers.m_floor
    local COLOR_BLACK = Helpers.COLOR_BLACK
    local v2_new = Helpers.v2_new
    local MOVESET_COLORS = Helpers.MOVESET_COLORS
    local formatVal = Helpers.formatVal
    local s_format = Helpers.s_format
    local ActiveMarks = Helpers.ActiveMarks
    local getGradientColor = Helpers.getGradientColor
    local DARK_MOVESETS = Helpers.DARK_MOVESETS
    local m_clamp = Helpers.m_clamp
    local COLOR_WHITE = Helpers.COLOR_WHITE

    local function parseRichTextLine(lineStr, defaultColor)
        local segments = {}
        local colorStack = { defaultColor }
        local pos = 1
        local len = #lineStr
    
        while pos <= len do
            local tagStart, tagEnd, tagName, tagAttr = lineStr:find("<(%/?%a+)%s*([^>]*)>", pos)
            if not tagStart then
                local text = lineStr:sub(pos)
                if #text > 0 then
                    table_insert(segments, {
                        Text = text,
                        Color = colorStack[#colorStack] or defaultColor
                    })
                end
                break
            end
    
            if tagStart > pos then
                local text = lineStr:sub(pos, tagStart - 1)
                if #text > 0 then
                    table_insert(segments, {
                        Text = text,
                        Color = colorStack[#colorStack] or defaultColor
                    })
                end
            end
    
            local isClosing = tagName:sub(1, 1) == "/"
            local cleanTagName = isClosing and tagName:sub(2):lower() or tagName:lower()
    
            if cleanTagName == "font" then
                if isClosing then
                    if #colorStack > 1 then
                        table.remove(colorStack)
                    end
                else
                    local hex = tagAttr:match("color%s*=%s*['\"]#?([%x%X]+)['\"]") or tagAttr:match("color%s*=%s*#?([%x%X]+)")
                    if hex then
                        local success, col = pcall(c3_fromHex, "#" .. hex)
                        if success and col then
                            table_insert(colorStack, col)
                        else
                            table_insert(colorStack, colorStack[#colorStack])
                        end
                    else
                        table_insert(colorStack, colorStack[#colorStack])
                    end
                end
            end
    
            pos = tagEnd + 1
        end
    
        return segments
    end
    
    local function renderRichText(pool, rawText, centerX, topY, fontSize, defaultColor)
        local lines = {}
        for line in rawText:gmatch("[^\r\n]+") do
            table_insert(lines, line)
        end
    
        if #lines == 0 then
            for _, obj in ipairs(pool) do
                obj.Visible = false
            end
            return
        end
    
        local poolIdx = 0
        local currentY = m_floor(topY)
        local lineHeight = fontSize + 2
    
        for _, lineStr in ipairs(lines) do
            local segments = parseRichTextLine(lineStr, defaultColor)
            local totalLineWidth = 0
            local segWidths = {}
    
            for i, seg in ipairs(segments) do
                poolIdx = poolIdx + 1
                local textObj = pool[poolIdx]
                if not textObj then
                    textObj = Drawing.new("Text")
                    textObj.Center = false
                    pool[poolIdx] = textObj
                end
    
                textObj.Size = fontSize
                textObj.Outline = true
                textObj.OutlineColor = COLOR_BLACK
                textObj.Text = seg.Text
                local w = textObj.TextBounds.X
                segWidths[i] = w
                totalLineWidth = totalLineWidth + w
            end
    
            local currentX = m_floor(centerX - (totalLineWidth / 2))
            local lineStartIdx = poolIdx - #segments + 1
    
            for i, seg in ipairs(segments) do
                local textObj = pool[lineStartIdx + i - 1]
                textObj.Position = v2_new(m_floor(currentX), currentY)
                textObj.Color = seg.Color
                textObj.Visible = true
                currentX = currentX + segWidths[i]
            end
    
            currentY = currentY + lineHeight
        end
    
        for i = poolIdx + 1, #pool do
            pool[i].Visible = false
        end
    end

    local function Hide(c)
        for _, textObj in ipairs(c.TextPool) do textObj.Visible = false end
    end

    local function Render(c, p, char, info, dist, movesetName, fullyCustom, isHaruta, miraclesObj, hideNameAndHealth, globalRainbowHex, shouldUpdateHeavy, scaleFactor, root2D, hasActiveMoveset, slotY, uY)
        if not toggleObject.Value then Hide(c); return end
        if shouldUpdateHeavy then
            local inUlt = char:GetAttribute("InUlt")
            local usesCustomLook = movesetName == "Custom" or fullyCustom
            local hexColor = usesCustomLook and globalRainbowHex or (MOVESET_COLORS[movesetName] or "FFFFFF")
            -- Cash
            local rawCash = p:GetAttribute("Cash")
            local cashValue = type(rawCash) == "number" and rawCash or 0
            if cashValue > 0 then
                local cashStr = hideNameAndHealth and tostring(cashValue) or formatVal(cashValue)
                c.CashDisplay = s_format("<font color='#00FF00'>$%s</font> | ", cashStr)
            else
                c.CashDisplay = ""
            end
    
            -- Perm badges
            local permBadges = ""
            if p:GetAttribute("PS_Owner") == true then
                permBadges = permBadges .. "<font color='#FFDF00'>[Owner]</font> "
            elseif p:GetAttribute("PS_Perms") == true then
                permBadges = permBadges .. "<font color='#FFAA00'>[Admin]</font> "
            end
            if p:GetAttribute("Workshop") == true then
                permBadges = permBadges .. "<font color='#AE00FF'>[Workshop]</font> "
            end
    
            -- Jackpot
            local rawJackpot = char:GetAttribute("JackpotInRow")
            local jackpotCount = type(rawJackpot) == "number" and rawJackpot or 0
            local jackpotTag = (jackpotCount > 0) and s_format("<font color='#00FF00'>[%sx JP]</font> ", jackpotCount) or ""
    
            local leftTag = inUlt and "<font color='#FF007F'>[ULT]</font> " or ""
            local afkTag = c.IsAFK and "<font color='#A0A0A0'>[AFK]</font> " or ""
            
            -- Mark
            local markTag = ""
            local markData = ActiveMarks[char]
            if markData and markData.mark and markData.mark.Parent and char.Parent then
                markTag = "<font color='#9D8D6D'><b>[MARK]</b></font> "
            else
                ActiveMarks[char] = nil
            end
    
            -- ITFG
            local itfgTag = ""
            local itfgVal = char:GetAttribute("ITFG")
            if type(itfgVal) == "number" and itfgVal >= 1 and itfgVal <= 2 then
                itfgTag = s_format("<font color='#DF00FF'><b>[IT %d/2]</b></font> ", itfgVal)
            end
    
            -- EXEC
            local execTag = ""
            local execVal = char:GetAttribute("EXEC")
            if type(execVal) == "number" and execVal > 0 then
                execTag = s_format("<font color='#FFFF00'><b>[EXEC %d/3]</b></font> ", execVal)
            end
    
            -- Burst
            local burstTag = ""
            if char:GetAttribute("Burst") ~= nil then
                burstTag = "<font color='#FFFFFF'><b>[BURST]</b></font> "
            end
    
            -- Emote
            local emoteTag = ""
            if info and info:FindFirstChild("Emote") then
                emoteTag = "<font color='#FF69B4'><b>[EMOTE]</b></font> "
            end
    
            -- VC
            local vcTag = ""
            local audioDevice = p:FindFirstChild("AudioDeviceInput")
            if audioDevice then
                local muted = audioDevice.Muted
                if muted == true then
                    vcTag = "<font color='#FF0000'><b>[VC]</b></font> "
                else
                    vcTag = "<font color='#00FF00'><b>[VC]</b></font> "
                end
            end
    
            local trailingBrackets = ""
            if markTag ~= "" then trailingBrackets = trailingBrackets .. markTag end
            if itfgTag ~= "" then trailingBrackets = trailingBrackets .. itfgTag end
            if execTag ~= "" then trailingBrackets = trailingBrackets .. execTag end
            if burstTag ~= "" then trailingBrackets = trailingBrackets .. burstTag end
            if emoteTag ~= "" then trailingBrackets = trailingBrackets .. emoteTag end
    
            -- Name line
            if hideNameAndHealth then
                c.NameDisplay = vcTag .. trailingBrackets
            elseif c.IsDead then
                c.NameDisplay = s_format("%s%s%s%s%s%s<font color='#FF0000'>[DEAD] %s</font> %s", afkTag, leftTag, jackpotTag, vcTag, c.GroupRoleTag, emoteTag, p.Name, trailingBrackets)
            else
                local nameColorHex = "FFFFFF"
                if c.IsFriend then
                    nameColorHex = "00FF00"
                elseif c.IsMutual then
                    nameColorHex = "00FFFF"
                end
    
                local nameStr = (dist < 50) and p.Name or "<b>" .. p.Name .. "</b>"
                c.NameDisplay = s_format("%s%s%s%s%s%s<font color='#%s'>%s</font> %s", afkTag, leftTag, jackpotTag, vcTag, permBadges, c.GroupRoleTag, nameColorHex, nameStr, trailingBrackets)
            end
            
            -- Distance color
            local distCol = getGradientColor(dist / 800)
            c.HexDistColor = s_format("%02x%02x%02x", m_floor(distCol.R * 255), m_floor(distCol.G * 255), m_floor(distCol.B * 255))
            
            -- Moveset label
            if movesetName and movesetName ~= "" then
                if DARK_MOVESETS[movesetName] and not usesCustomLook then
                    c.CachedMoveset = s_format("<stroke color='#FFFFFF' thickness='1'><font color='#%s'>%s</font></stroke> | ", hexColor, tostring(movesetName))
                else
                    c.CachedMoveset = s_format("<font color='#%s'>%s</font> | ", hexColor, tostring(movesetName))
                end
            else
                c.CachedMoveset = ""
            end
    
            -- Extra info
            local extra = ""
            if isHaruta and miraclesObj then
                local harutaHex = MOVESET_COLORS["Haruta"] or "A77DCB"
                extra = extra .. s_format(" • <font color='#%s'>%s</font>", harutaHex, tostring(miraclesObj.Value))
            end
            if c.AgeDisplay and c.AgeDisplay ~= "" then
                extra = extra .. " • " .. c.AgeDisplay
            end
            if c.FriendDisplay and c.FriendDisplay ~= "" then
                extra = extra .. " • " .. c.FriendDisplay
            end
            if c.GamepassDisplay and c.GamepassDisplay ~= "" then
                extra = extra .. " • " .. c.GamepassDisplay
            end
            c.ExtraInfo = extra
        end
        -- 7. Main Overhead Text
        local killString = hideNameAndHealth and tostring(c.CachedKills) or formatVal(c.CachedKills)
        if c.IsHidingKills then
            killString = s_format("%s <font color='#FF3333'><b>[HIDDEN]</b></font>", killString)
        end
    
        local rawText = s_format("%s\n%s%s<font color='#%s'>%s</font> • <font color='#%s'>%sm</font>%s", 
            c.NameDisplay, 
            c.CachedMoveset,
            c.CashDisplay,
            c.HexKillColor, 
            killString, 
            c.HexDistColor, 
            tostring(m_floor(c.LastDist)),
            c.ExtraInfo
        )
    
        local mainFontSize = m_floor(m_clamp(13 * scaleFactor, 9, 18))
        local textY = hasActiveMoveset and (slotY - mainFontSize - m_floor(m_clamp(10 * scaleFactor, 6, 14))) or (uY - mainFontSize - m_floor(m_clamp(10 * scaleFactor, 6, 14)))
        renderRichText(c.TextPool, rawText, m_floor(root2D.X), textY, mainFontSize, COLOR_WHITE)
    end

    return { Render = Render, Hide = Hide }
end

return PlayerInfo
