    table.insert(State.Connections, toggleConn)
    handleToggleChange()

    -- Reach variable setup
    local reachConn = reachVariable:GetPropertyChangedSignal("Value"):Connect(handleReachChange)
    table.insert(State.Connections, reachConn)
    handleReachChange()
end

return Reach
